# Remnants of HTML entities that survive tokenization when a corpus file was
# stored escaped (Hebrew gershayim are &quot; in word/document.xml). The docx
# reader now unescapes before analysis, but .md/.txt corpus files can still
# arrive pre-escaped, and "quot" outranking every real word poisons the
# vocabulary steering the write skill reads off frequentTerms.
ENTITY_REMNANTS = {
    "quot",
    "amp",
    "apos",
    "nbsp",
    "lt",
    "gt",
    "ndash",
    "mdash",
    "rsquo",
    "lsquo",
    "rdquo",
    "ldquo",
}

STOPWORDS = HEBREW_STOPWORDS | ENGLISH_STOPWORDS | ENTITY_REMNANTS


def _normalize(word: str) -> str:
    return word if HEBREW_CHAR_RE.search(word) else word.lower()


def _content_terms(text: str, min_len: int) -> list[str]:
    return [
        _normalize(w)
        for w in tokenize_words(text)
        if len(w) >= min_len and _normalize(w) not in STOPWORDS
    ]


def find_structural_furniture_terms(
    documents: list[str],
    min_len: int,
    max_words: int,
    share: float,
    min_count: int,
    top_n: int = 30,
    candidate_multiplier: int = 3,
) -> set[str]:
    """Terms that belong to the document's furniture, not the writer's prose.

    Corpus files are coursework and papers whose tables of contents and section
    headers repeat the author's name, the assignment number and the course
    name. Those lines are *paragraphs* to the splitter, so their words land in
    frequentTerms — which the write skill reads to steer vocabulary, meaning
    the researcher's own name was being fed back as a word to reach for.

    The signal is paragraph LENGTH, not position. Measured on a real 10-file
    corpus (857 paragraphs, median 38 words): the paragraphs carrying the
    author's name are TOC entries and headers with a median of 5 words —
    "מטלה 2 - יוליוס ולהאוזן - יותם פרום 4" — and 96% of that name's
    occurrences sit in paragraphs of 10 words or fewer, against 3% for real
    subject vocabulary like שד״ל or המקרא. A term is furniture when at least
    `share` of its occurrences fall in paragraphs of at most `max_words`
    words, and it occurs at least `min_count` times so a rare word is not
    dropped on noise.

    Only terms in CONTENTION for the reported list are judged — the top
    `top_n * candidate_multiplier` by raw count. The filter exists to keep
    furniture out of frequentTerms, so a term that could never be reported does
    not need classifying, and classifying it anyway is actively harmful: a
    share computed over a handful of occurrences has no resolution. Measured
    case, ב׳ against א׳ — the same token doing the same job in the same two
    files — landed at 0.80 and 0.50 on five and seven observations, so one was
    dropped and the other kept. Under the contention gate neither is judged
    (ranks 1487 and 708 of a 90-term field), while the terms that actually
    reach the list — the author's name at ranks 32 and 33, מטלה at 40 — still
    are. `min_count` stays as an absolute floor for corpora small enough that
    everything is nominally in contention.

    This replaces a front-matter rule shipped in 0.7.3 that looked at the first
    N paragraphs of each file. It never fired: the headers repeat THROUGHOUT
    each document, one per assignment, so almost none of them are front matter.
    """
    paragraphs = [p for doc in documents for p in split_paragraphs(doc)]
    if not paragraphs:
        return set()

    short_counts: Counter[str] = Counter()
    total_counts: Counter[str] = Counter()
    for paragraph in paragraphs:
        found = _content_terms(paragraph, min_len)
        total_counts.update(found)
        if len(tokenize_words(paragraph)) <= max_words:
            short_counts.update(found)

    contenders = {
        term
        for term, _ in total_counts.most_common(max(top_n * candidate_multiplier, top_n))
    }

    return {
        term
        for term, count in total_counts.items()
        if term in contenders
        and count >= min_count
        and short_counts[term] / count >= share
    }


def compute_frequent_terms(
    text: str,
    top_n: int,
    min_len: int,
    documents: list[str] | None = None,
    furniture_max_words: int = 10,
    furniture_share: float = 0.8,
    furniture_min_count: int = 5,
    furniture_candidate_multiplier: int = 3,
) -> list[dict]:
    """Top-N content terms. Pass `documents` (the per-file texts) to also drop
    structural furniture — TOC lines and section headers, which are only
    separable from prose when paragraph boundaries survive."""
    furniture: set[str] = set()
    if documents:
        furniture = find_structural_furniture_terms(
            documents,
            min_len,
            furniture_max_words,
            furniture_share,
            furniture_min_count,
            top_n,
            furniture_candidate_multiplier,
        )

    normalized = [t for t in _content_terms(text, min_len) if t not in furniture]
    total = len(normalized)
    counts = Counter(normalized)
    results = []
    for term, count in counts.most_common(top_n):
        results.append(
            {
                "term": term,
                "count": count,
                "frequency": round(count / total, 5) if total else 0.0,
            }
        )
    return results
